    48|export type RuntimeVariableSpec = {
    49|  /** Canonical variable name. */
    50|  name: string;
    51|  /** Alternative env names that satisfy this variable (first present wins). */
    52|  aliases: string[];
    53|  isPublic: boolean;
    54|  scopes: VarScope[];
    55|  usedBy: string[];
    56|  verify: VarVerifyKind;
    57|  /** Declared in the project's Rork env panel (public or private list). */
    58|  knownInRork: boolean;
    59|  /** Honest one-line description of the variable's role. */
    60|  description: string;
    61|};
