   111|/** Mask a secret: first 3 + last 2 visible, short values fully masked. Never the raw value. */
   112|export function maskSecret(value: string): string {
   113|  const len = value.length;
   114|  if (len === 0) return '';
   115|  if (len <= 6) return '*'.repeat(len);
   116|  return `${value.slice(0, 3)}${'*'.repeat(Math.max(4, len - 5))}${value.slice(-2)}`;
   117|}
