   119|/** True for client-inlined public variables (EXPO_PUBLIC_ / VITE_ / RORK_PUBLIC_). */
   120|export function isPublicClientVar(name: string): boolean {
   121|  return /^(EXPO_PUBLIC_|VITE_|RORK_PUBLIC_)/.test(name);
   122|}
