   227|function classifyPresence(spec: RuntimeVariableSpec, present: boolean): VarStatus {
   228|  if (present) return 'PRESENT_IN_RUNTIME';
   229|  return spec.knownInRork ? 'PRESENT_IN_RORK_NOT_INJECTED' : 'MISSING_FROM_RORK';
