   232|/** Build the presence/status report from an env snapshot (no network). */
   233|export function buildRuntimeVariablesReport(
   234|  env: EnvSnapshot = process.env,
   235|  runtimeLabel: string = resolveRuntimeLabel(env),
   236|): RuntimeVariablesReport {
   237|  const variables: RuntimeVariableStatus[] = RUNTIME_VARIABLE_SPECS.map((spec) => {
   238|    const { from, value } = resolveValue(env, spec);
   239|    const present = value.length > 0;
   240|    return {
   241|      name: spec.name,
   242|      aliases: spec.aliases,
   243|      isPublic: spec.isPublic,
   244|      scopes: spec.scopes,
   245|      usedBy: spec.usedBy,
   246|      verifyKind: spec.verify,
   247|      knownInRork: spec.knownInRork,
   248|      description: spec.description,
   249|      resolvedFrom: from,
   250|      present,
   251|      masked: present ? maskSecret(value) : null,
   252|      valueLength: value.length,
   253|      status: classifyPresence(spec, present),
   254|      publicWarning: isPublicClientVar(from ?? spec.name),
   255|      lastVerifiedAt: null,
   256|      verifyDetail: null,
   257|    };
   258|  });
   259|
   260|  const presentCount = variables.filter((v) => v.present).length;
   261|  return {
   262|    marker: IVX_RUNTIME_VARIABLES_MARKER,
   263|    generatedAt: new Date().toISOString(),
   264|    runtimeLabel,
   265|    total: variables.length,
   266|    present: presentCount,
   267|    missing: variables.length - presentCount,
   268|    variables,
   269|  };
