   278|export type VariableVerification = {
   279|  name: string;
   280|  verifyKind: VarVerifyKind;
   281|  status: VarStatus;
   282|  ok: boolean;
   283|  httpStatus: number | null;
   284|  detail: string;
   285|  verifiedAt: string;
   286|};
   287|
   288|async function probe(fetchImpl: FetchLike, url: string, init: RequestInit, timeoutMs = 8000): Promise<{ status: number | null; ok: boolean; bodySnippet: string }> {
   289|  const controller = new AbortController();
   290|  const timer = setTimeout(() => controller.abort(), timeoutMs);
   291|  try {
   292|    const response = await fetchImpl(url, { ...init, signal: controller.signal });
   293|    let bodySnippet = '';
   294|    try {
   295|      bodySnippet = (await response.text()).slice(0, 200);
   296|    } catch {
   297|      bodySnippet = '';
   298|    }
   299|    return { status: response.status, ok: response.ok, bodySnippet };
   300|  } catch (error) {
   301|    const message = error instanceof Error ? error.message : 'network error';
   302|    return { status: null, ok: false, bodySnippet: message };
   303|  } finally {
   304|    clearTimeout(timer);
   305|  }
   306|}
   307|
   308|function statusFromHttp(httpStatus: number | null): VarStatus {
   309|  if (httpStatus === null) return 'PRESENT_BUT_INVALID';
   310|  if (httpStatus === 401 || httpStatus === 403) return 'PRESENT_BUT_UNAUTHORIZED';
   311|  if (httpStatus >= 200 && httpStatus < 300) return 'VERIFIED';
   312|  return 'PRESENT_BUT_INVALID';
   313|}
   314|
   315|/**
   316| * Run a REAL verification probe for a single variable. Returns pass/fail + HTTP
   317| * status only — never the secret value. Variables without a safe live probe are
   318| * validated by presence + format and labeled honestly.
   319| */
   320|export async function verifyVariable(
   321|  name: string,
   322|  env: EnvSnapshot = process.env,
   323|  fetchImpl: FetchLike = fetch,
   324|): Promise<VariableVerification> {
   325|  const verifiedAt = new Date().toISOString();
   326|  const spec = RUNTIME_VARIABLE_SPECS.find((s) => s.name === name);
   327|  if (!spec) {
   328|    return { name, verifyKind: 'format_only', status: 'MISSING_FROM_RORK', ok: false, httpStatus: null, detail: 'Unknown variable.', verifiedAt };
   329|  }
   330|
   331|  const { value } = resolveValue(env, spec);
   332|  if (value.length === 0) {
   333|    return {
   334|      name, verifyKind: spec.verify,
   335|      status: spec.knownInRork ? 'PRESENT_IN_RORK_NOT_INJECTED' : 'MISSING_FROM_RORK',
   336|      ok: false, httpStatus: null,
   337|      detail: spec.knownInRork
   338|        ? 'Declared in Rork but not present in this runtime — sync it into the runtime scope.'
   339|        : 'Not present in Rork or this runtime.',
   340|      verifiedAt,
   341|    };
   342|  }
   343|
   344|  switch (spec.verify) {
   345|    case 'github': {
   346|      const token = trimmed(env.GITHUB_TOKEN);
   347|      const repoUrl = trimmed(env.GITHUB_REPO_URL);
   348|      const repoPath = parseGithubRepoPath(repoUrl);
   349|      if (!token) {
   350|        return { name, verifyKind: spec.verify, status: 'PRESENT_BUT_INVALID', ok: false, httpStatus: null, detail: 'GITHUB_TOKEN required to verify GitHub access.', verifiedAt };
   351|      }
   352|      const url = repoPath ? `https://api.github.com/repos/${repoPath}` : 'https://api.github.com/user';
   353|      const r = await probe(fetchImpl, url, { headers: { Authorization: `Bearer ${token}`, Accept: 'application/vnd.github+json', 'User-Agent': 'ivx-runtime-variables' } });
   354|      return { name, verifyKind: spec.verify, status: statusFromHttp(r.status), ok: r.ok, httpStatus: r.status, detail: r.ok ? `Authenticated GitHub read OK (${repoPath ? `repo ${repoPath}` : 'user'}).` : `GitHub returned HTTP ${r.status ?? 'network-error'}.`, verifiedAt };
   355|    }
   356|    case 'render': {
   357|      const key = trimmed(env.RENDER_API_KEY);
   358|      const serviceId = trimmed(env.RENDER_SERVICE_ID);
   359|      if (!key || !serviceId) {
   360|        return { name, verifyKind: spec.verify, status: 'PRESENT_BUT_INVALID', ok: false, httpStatus: null, detail: 'RENDER_API_KEY + RENDER_SERVICE_ID both required.', verifiedAt };
   361|      }
   362|      const r = await probe(fetchImpl, `https://api.render.com/v1/services/${encodeURIComponent(serviceId)}`, { headers: { Authorization: `Bearer ${key}`, Accept: 'application/json' } });
   363|      return { name, verifyKind: spec.verify, status: statusFromHttp(r.status), ok: r.ok, httpStatus: r.status, detail: r.ok ? 'Render service lookup OK.' : `Render API returned HTTP ${r.status ?? 'network-error'}.`, verifiedAt };
   364|    }
   365|    case 'supabase_anon': {
   366|      const url = trimmed(env.EXPO_PUBLIC_SUPABASE_URL) || trimmed(env.SUPABASE_URL);
   367|      const anon = trimmed(env.EXPO_PUBLIC_SUPABASE_ANON_KEY);
   368|      if (!url || !anon) {
   369|        return { name, verifyKind: spec.verify, status: 'PRESENT_BUT_INVALID', ok: false, httpStatus: null, detail: 'EXPO_PUBLIC_SUPABASE_URL + EXPO_PUBLIC_SUPABASE_ANON_KEY required.', verifiedAt };
   370|      }
   371|      const r = await probe(fetchImpl, `${url.replace(/\/+$/, '')}/rest/v1/?apikey=${encodeURIComponent(anon)}`, { headers: { apikey: anon, Authorization: `Bearer ${anon}` } });
   372|      return { name, verifyKind: spec.verify, status: statusFromHttp(r.status), ok: r.ok, httpStatus: r.status, detail: r.ok ? 'Supabase anon REST health OK.' : `Supabase REST returned HTTP ${r.status ?? 'network-error'}.`, verifiedAt };
   373|    }
   374|    case 'supabase_service': {
   375|      const url = trimmed(env.EXPO_PUBLIC_SUPABASE_URL) || trimmed(env.SUPABASE_URL);
   376|      const key = trimmed(env.SUPABASE_SERVICE_ROLE_KEY);
   377|      if (!url || !key) {
   378|        return { name, verifyKind: spec.verify, status: 'PRESENT_BUT_INVALID', ok: false, httpStatus: null, detail: 'EXPO_PUBLIC_SUPABASE_URL + SUPABASE_SERVICE_ROLE_KEY required.', verifiedAt };
   379|      }
   380|      const r = await probe(fetchImpl, `${url.replace(/\/+$/, '')}/rest/v1/jv_deals?select=id&limit=1`, { headers: { apikey: key, Authorization: `Bearer ${key}`, Accept: 'application/json' } });
   381|      return { name, verifyKind: spec.verify, status: statusFromHttp(r.status), ok: r.ok, httpStatus: r.status, detail: r.ok ? 'Service-role table inspection OK (jv_deals readable).' : `Supabase service-role read returned HTTP ${r.status ?? 'network-error'}.`, verifiedAt };
   382|    }
   383|    case 'production': {
   384|      const base = trimmed(env.PRODUCTION_BASE_URL) || trimmed(env.EXPO_PUBLIC_IVX_API_BASE_URL) || trimmed(env.EXPO_PUBLIC_IVX_API);
   385|      if (!base) {
   386|        return { name, verifyKind: spec.verify, status: 'PRESENT_BUT_INVALID', ok: false, httpStatus: null, detail: 'No production base URL configured.', verifiedAt };
   387|      }
   388|      const r = await probe(fetchImpl, `${base.replace(/\/+$/, '')}/health`, { headers: { Accept: 'application/json' } });
   389|      return { name, verifyKind: spec.verify, status: statusFromHttp(r.status), ok: r.ok, httpStatus: r.status, detail: r.ok ? 'Production /health returned 200.' : `Production /health returned HTTP ${r.status ?? 'network-error'}.`, verifiedAt };
   390|    }
   391|    case 'ai_gateway': {
   392|      // No-cost live model ping is not run here; validate presence + plausible format honestly.
   393|      const looksValid = value.length >= 20;
   394|      return { name, verifyKind: spec.verify, status: looksValid ? 'PRESENT_IN_RUNTIME' : 'PRESENT_BUT_INVALID', ok: looksValid, httpStatus: null, detail: looksValid ? 'Present + plausible length; live model ping not run (cost-gated).' : 'Value too short to be a valid key.', verifiedAt };
   395|    }
   396|    case 'aws': {
   397|      const looksValid = name === 'AWS_ACCESS_KEY_ID' ? /^(AKIA|ASIA)[A-Z0-9]{12,}$/.test(value) : value.length >= 20;
   398|      return { name, verifyKind: spec.verify, status: looksValid ? 'PRESENT_IN_RUNTIME' : 'PRESENT_BUT_INVALID', ok: looksValid, httpStatus: null, detail: looksValid ? 'Present + format valid; live STS GetCallerIdentity (SigV4) not run.' : 'Value does not match the expected AWS format.', verifiedAt };
   399|    }
   400|    case 'owner_token': {
   401|      const looksValid = value.length >= 32;
   402|      return { name, verifyKind: spec.verify, status: looksValid ? 'PRESENT_IN_RUNTIME' : 'PRESENT_BUT_INVALID', ok: looksValid, httpStatus: null, detail: looksValid ? 'Present + sufficient length; owner-gated routes accept this token live.' : 'Owner token too short.', verifiedAt };
   403|    }
   404|    case 'format_only':
   405|    default: {
   406|      return { name, verifyKind: 'format_only', status: 'PRESENT_IN_RUNTIME', ok: true, httpStatus: null, detail: 'Present in runtime (format-only check).', verifiedAt };
   407|    }
   408|  }
   409|}
